OLD_RECONCILE = '    private func reconcile(_ value: ProfileEditSnapshot) {\n        guard let unresolved = pending[value.id] else { return }\n        let matches = unresolved.payload.matches(value)\n        if unresolved.acknowledged && matches {\n            pending[value.id] = nil; messageKey = "profile.edit.saved"; onSaved()\n        } else if matches {\n            // The current fields may match while an unacknowledged request is still\n            // running. Keep the lock across subsequent reads, navigation and reauth.\n            messageKey = "profile.edit.readbackUnconfirmed"\n        } else { messageKey = "profile.edit.unknown" }\n    }\n\n}\n'
OLD_ORDINARY_SAVE = '    public func save(_ payload: ProfileEditPayload, token: String) async throws {\n        var prepared: URLRequest\n        do {\n            prepared = try request("api/user/update", token: token)\n            prepared.setValue("application/json", forHTTPHeaderField: "Content-Type")\n            prepared.httpBody = try JSONEncoder().encode(payload)\n            try Task.checkCancellation()\n        } catch { throw ProfileEditWriteError.notSent }\n        let data: Data, status: Int\n        do { (data, status) = try await transport.send(prepared) }\n        catch { throw ProfileEditWriteError.outcomeUnknown }\n        guard !Task.isCancelled else { throw ProfileEditWriteError.outcomeUnknown }\n        let envelope = try? JSONDecoder().decode(Response.self, from: data)\n        if status == 401 || status == 403 {\n            throw ProfileEditWriteError.rejected(.init(httpStatus: status, code: envelope?.code, message: envelope?.msg))\n        }\n        guard (200..<300).contains(status), let envelope else { throw ProfileEditWriteError.outcomeUnknown }\n        guard envelope.code == 200 else {\n            throw ProfileEditWriteError.rejected(.init(code: envelope.code, message: envelope.msg))\n        }\n    }'

class AvatarContracts(unittest.TestCase):
    def setUp(self):
        self.upload=(ROOT/'Core/ProfileAvatarUpload.swift').read_text()
        self.flow=(ROOT/'Core/ProfileAvatarFlow.swift').read_text()
        self.journal=(ROOT/'Core/ProfileAvatarJournal.swift').read_text()
        self.coordinator=(ROOT/'Core/ProfileEditCoordinator.swift').read_text()
        self.service=(ROOT/'Core/ProfileEditService.swift').read_text()
        self.view=(ROOT/'App/ProfileEditView.swift').read_text()
        self.section=(ROOT/'App/ProfileAvatarDraftSection.swift').read_text()
    def test_four_shared_file_inverses_restore_exact_frozen19(self):
        for path,proof in INVERSES.items():
            value=(ROOT/path).read_bytes()
            for offset,after,before in reversed(proof['hunks']):
                self.assertEqual(value[offset:offset+len(after)],after,path)
                value=value[:offset]+before+value[offset+len(after):]
            self.assertEqual(hashlib.sha256(value).hexdigest(),proof['base_sha256'],path)
    def test_twenty_eight_protected_paths_are_unchanged(self):
        self.assertEqual(len(PROTECTED),28)
        for path,digest in PROTECTED.items():self.assertEqual(hashlib.sha256((ROOT/path).read_bytes()).hexdigest(),digest,path)
    def test_original_pending_reconciliation_is_byte_exact(self):
        self.assertEqual(self.coordinator[self.coordinator.index('    private func reconcile('):],OLD_RECONCILE)
    def test_ordinary_service_save_is_unchanged_behind_image_rejection(self):
        method=self.service[self.service.index('    public func save('):self.service.index('    @MainActor public func saveAvatar(')]
        method=method.replace('        guard payload.avatarReplacement == nil else { throw ProfileEditWriteError.notSent }\n','').rstrip()
        self.assertEqual(method,OLD_ORDINARY_SAVE.rstrip())
    def test_upload_and_image_save_never_fall_back_to_generic_http(self):
        self.assertIn('transport: (any ProfileAvatarDispatching)? = nil',self.upload)
        self.assertIn('avatarTransport: (any ProfileAvatarDispatching)? = nil',self.service)
        avatar=self.service[self.service.index('    @MainActor public func saveAvatar('):]
        self.assertNotIn('transport.send(',avatar)
        for token in ['URLSession(', 'ResponseLimitedHTTPTransport(enabled: true', 'runtimeHTTPTransport', 'AppSession(']:self.assertNotIn(token,self.upload+self.flow+self.section)
    def test_final_forward_is_exact_current_single_use_and_synchronous(self):
        self.assertIn('!didForward, self.request == request, !Task.isCancelled, validity()',self.upload)
        forward=self.upload[self.upload.index('    public func forward('):self.upload.index('    func isCurrent()')]
        self.assertNotIn('await ', '\n'.join(line.split('//')[0] for line in forward.splitlines()))
        self.assertLess(forward.index('validity()'),forward.index('try start()'))
        self.assertIn('transport.send(request, authorization: authorization)',self.upload)
        self.assertIn('avatarTransport.send(prepared, authorization: authorization)',self.service)
    def test_both_callers_require_actual_forward_and_map_after_forward_uncertainty(self):
        for token in ['authorization.didForward', 'authorization.isCurrent()']:
            self.assertIn(token,self.upload);self.assertIn(token,self.service)
        self.assertIn('authorization.didForward ? ProfileAvatarFailure.unknown : ProfileAvatarFailure.notSent',self.upload)
        self.assertIn('authorization.didForward ? ProfileEditWriteError.outcomeUnknown : ProfileEditWriteError.notSent',self.service)
    def test_exact_source_route_square_jpeg_and_bounded_origin_reference(self):
        for token in ['api/common/uploadOSS','image_1_1','avatar.jpg','image.width == image.height','64 * 1024','value.utf8.count <= 8192','RetainedImageOrigin.accepts']:
            self.assertIn(token,self.upload)
        self.assertNotIn('image_free',self.upload)
        self.assertNotIn('refundId',self.upload)
    def test_account_epoch_viewer_approval_editor_lifetime_and_raw_hash_fences(self):
        for token in ['viewerRevision','approvalID','editorID','lifetimeID','snapshotHash','draftHash','draftRevision','ProfileAvatarExact.snapshot','ProfileAvatarExact.draft']:
            self.assertIn(token,self.upload)
        self.assertIn('token.utf8.elementsEqual(session.token.utf8)',self.upload)
        self.assertIn('self.credentials() == original && self.isCurrent(target.scope) && ownerCurrent()',self.upload)
    def test_missing_journal_is_unavailable_and_metadata_has_no_receipt_url(self):
        self.assertIn('throw ProfileAvatarFailure.disabled',self.journal)
        self.assertIn('guard let journal else { state = .unknown; return }',self.flow)
        stored=self.journal[self.journal.index('public struct ProfileAvatarJournalEntry'):self.journal.index('@MainActor public protocol')]
        for token in ['reference:', 'token:', 'jpeg:', 'avatar:', 'Data'] :self.assertNotIn(token,stored)
        self.assertIn('try write(bytes, entry.key.storageKey)',self.journal)
        self.assertIn('try read(entry.key.storageKey) == bytes',self.journal)
    def test_unknown_upload_cannot_be_retried_or_falsely_reconciled(self):
        self.assertIn('self == .locallyStaged || self == .rejected',self.journal)
        self.assertIn('!old.phase.permitsNewSelection { state = .unknown }',self.flow)
        self.assertNotIn('func reset(',self.journal)
        self.assertNotIn('func clear(',self.journal)
        self.assertNotIn('case (.pending, .locallyStaged)',self.journal)
        self.assertIn('Never reset/remove a durable pending or uncertain attempt',self.flow)
    def test_upload_review_and_attachment_are_separate_explicit_steps(self):
        for token in ['public func prepare(', 'public func confirm(', 'public func stage()'] :self.assertIn(token,self.flow)
        self.assertIn('try journal.begin(',self.flow)
        self.assertLess(self.flow.index('try journal.begin('),self.flow.index('try await source.upload('))
        self.assertIn('received.id == attempt, received.target == target, received.selectedDigest == digest',self.flow)
        self.assertIn('receipt = received',self.flow)
        self.assertIn('state == .uploaded, task == nil, ownsTarget',self.flow)
    def test_stage_preserves_receipt_until_all_fences_and_verified_record(self):
        stage=self.flow[self.flow.index('    public func stage()'):self.flow.index('    public func close()')]
        self.assertLess(stage.index('phase: .stageReserved'),stage.index('apply(replacement)'))
        self.assertLess(stage.index('guard ownsTarget'),stage.index('apply(replacement)'))
        self.assertIn('currentDraft()?.avatarReplacement == replacement',stage)
        self.assertIn('entry.phase == .locallyStaged',stage)
    def test_payload_encodes_only_existing_six_wire_fields(self):
        source=(ROOT/'Core/ProfileEditContracts.swift').read_text()
        self.assertIn('case name, introduction, avatar, wechat, casePics, tagIds',source)
        self.assertIn('draft.avatarReplacement?.reference ?? snapshot.avatar; wechat = snapshot.wechat; casePics = snapshot.casePics',source)
